import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.DQOulFGV.js";const b=JSON.parse('{"title":"Database Integration","description":"","frontmatter":{},"headers":[],"relativePath":"database.md","filePath":"database.md"}'),p={name:"database.md"};function i(l,a,o,r,d,c){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="database-integration" tabindex="-1">Database Integration <a class="header-anchor" href="#database-integration" aria-label="Permalink to &quot;Database Integration&quot;">​</a></h1><p>Mamba natively links SQLite (<code>-lsqlite3</code>) into your compiled binaries. This eliminates the need for separate database server processes for embedded data tasks.</p><h2 id="opening-a-database" tabindex="-1">Opening a Database <a class="header-anchor" href="#opening-a-database" aria-label="Permalink to &quot;Opening a Database&quot;">​</a></h2><p>Initialize a connection using the <code>db.open()</code> command. This creates the <code>.db</code> file if it does not exist.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let conn = db.open(&quot;app.db&quot;)</span></span></code></pre></div><h2 id="parameterized-queries-safe-sql" tabindex="-1">Parameterized Queries (Safe SQL) <a class="header-anchor" href="#parameterized-queries-safe-sql" aria-label="Permalink to &quot;Parameterized Queries (Safe SQL)&quot;">​</a></h2><p>Always use parameterized queries (<code>?</code>) to prevent SQL injection. Mamba securely binds parameters natively.</p><h3 id="creating-tables" tabindex="-1">Creating Tables <a class="header-anchor" href="#creating-tables" aria-label="Permalink to &quot;Creating Tables&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db.query(&quot;CREATE TABLE IF NOT EXISTS users (name TEXT, role TEXT)&quot;)</span></span></code></pre></div><h3 id="inserting-data" tabindex="-1">Inserting Data <a class="header-anchor" href="#inserting-data" aria-label="Permalink to &quot;Inserting Data&quot;">​</a></h3><p>Provide parameters as a Mamba array in the second argument.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db.query(</span></span>
<span class="line"><span>    &quot;INSERT INTO users (name, role) VALUES (?, ?)&quot;,</span></span>
<span class="line"><span>    [&quot;Alex&quot;, &quot;Admin&quot;]</span></span>
<span class="line"><span>)</span></span></code></pre></div><h3 id="selecting-data" tabindex="-1">Selecting Data <a class="header-anchor" href="#selecting-data" aria-label="Permalink to &quot;Selecting Data&quot;">​</a></h3><p><code>db.query</code> on a <code>SELECT</code> statement returns a JSON-compatible string array of results.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let users = db.query(&quot;SELECT * FROM users&quot;)</span></span>
<span class="line"><span>print(users)</span></span></code></pre></div><h2 id="web-database-example" tabindex="-1">Web + Database Example <a class="header-anchor" href="#web-database-example" aria-label="Permalink to &quot;Web + Database Example&quot;">​</a></h2><p>This is a hero example demonstrating a fully functional SQLite-backed API in Mamba.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db.open(&quot;users.db&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>db.query(&quot;CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>route POST &quot;/api/users&quot; {</span></span>
<span class="line"><span>    let body = req.body()</span></span>
<span class="line"><span>    let user = json.parse(body)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    db.query(</span></span>
<span class="line"><span>        &quot;INSERT INTO users (name, email) VALUES (?, ?)&quot;,</span></span>
<span class="line"><span>        [user[&quot;name&quot;], user[&quot;email&quot;]]</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return json.stringify({</span></span>
<span class="line"><span>        &quot;status&quot;: &quot;created&quot;</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Architecture Flow:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>React / Client</span></span>
<span class="line"><span>      ↓ (HTTP POST)</span></span>
<span class="line"><span>Mamba Web Route</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>JSON Parse Payload</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Prepared Statement Binding</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>SQLite Engine</span></span></code></pre></div>`,20)])])}const h=s(p,[["render",i]]);export{b as __pageData,h as default};
